"""Regenerate db/schema.sql (Postgres DDL) from store/schema.py, the source of truth.

Usage (from services/api):  python scripts/dump_schema.py
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from sqlalchemy.dialects import postgresql  # noqa: E402
from sqlalchemy.schema import CreateIndex, CreateTable  # noqa: E402

from config import ROOT  # noqa: E402
from store.schema import metadata  # noqa: E402

dialect = postgresql.dialect()
parts = [
    "-- Generated by services/api/scripts/dump_schema.py from store/schema.py. Do not edit by hand.",
    "-- The API creates these tables itself (store/db.py create_all); this file is for reference and review.",
    "",
    "create extension if not exists vector;",
    "",
]
for table in metadata.sorted_tables:
    parts.append(str(CreateTable(table).compile(dialect=dialect)).strip() + ";")
    for index in table.indexes:
        parts.append(str(CreateIndex(index).compile(dialect=dialect)).strip() + ";")
    parts.append("")
(ROOT / "db" / "schema.sql").write_text("\n".join(parts))
print(f"Wrote {ROOT / 'db' / 'schema.sql'} ({len(metadata.sorted_tables)} tables)")
